using System.Data;
using System.Text.Json;
using Microsoft.Data.SqlClient;
using SmaComplaints.Models;
namespace SmaComplaints.Data;
public sealed class SqlFormStore(IConfiguration configuration):IFormStore
{
 SqlConnection Connection()=>new(configuration.GetConnectionString("Complaints"));
 static void P(SqlCommand c,string key,object? value)=>c.Parameters.AddWithValue(key,value??DBNull.Value);
 public async Task<List<FormSummary>> SummariesAsync(bool drafts=false){await using var db=Connection();await db.OpenAsync();await using var c=db.CreateCommand();c.CommandText="SELECT TOP(100) Id,Name,State,Revision,(SELECT COUNT(*) FROM OPENJSON(Payload,'$.Fields')),(SELECT COUNT(*) FROM OPENJSON(Payload,'$.Steps')),SourceName FROM dbo.FormDefinitions WHERE @Drafts=1 OR State='Published' ORDER BY Name";P(c,"@Drafts",drafts);var result=new List<FormSummary>();try{await using var r=await c.ExecuteReaderAsync();while(await r.ReadAsync())result.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetInt32(3),r.GetInt32(4),r.GetInt32(5),r.GetString(6)));}catch(SqlException ex)when(ex.Number==208){throw new WorkflowException("Form Studio needs the 002_forms.sql database migration. Run --initialize-database before using it.");}return result;}
 public async Task<FormDefinition?> DefinitionAsync(Guid id){await using var db=Connection();await db.OpenAsync();await using var c=db.CreateCommand();c.CommandText="SELECT Payload,Revision FROM dbo.FormDefinitions WHERE Id=@Id";P(c,"@Id",id);await using var r=await c.ExecuteReaderAsync();if(!await r.ReadAsync())return null;var d=JsonSerializer.Deserialize<FormDefinition>(r.GetString(0))!;d.Revision=r.GetInt32(1);return d;}
 public async Task SaveDefinitionAsync(FormDefinition d,int expected,byte[]? source=null){await using var db=Connection();await db.OpenAsync();await using var c=db.CreateCommand();d.Revision=expected+1;c.CommandText=expected==0?"INSERT dbo.FormDefinitions(Id,Name,State,Revision,Payload,SourceName,SourceBytes) VALUES(@Id,@Name,@State,@Rev,@Json,@Source,@Bytes)":"UPDATE dbo.FormDefinitions SET Name=@Name,State=@State,Revision=@Rev,Payload=@Json WHERE Id=@Id AND Revision=@Expected";P(c,"@Id",d.Id);P(c,"@Name",d.Name);P(c,"@State",d.State);P(c,"@Rev",d.Revision);P(c,"@Json",JsonSerializer.Serialize(d));P(c,"@Expected",expected);P(c,"@Source",d.SourceName);c.Parameters.Add("@Bytes",SqlDbType.VarBinary,-1).Value=(object?)source??DBNull.Value;try{if(await c.ExecuteNonQueryAsync()!=1)throw new ConcurrencyConflictException();}catch(SqlException ex)when(ex.Number is 2601 or 2627){throw new WorkflowException("A published module already has this name.");}}
 public async Task<byte[]?> SourceAsync(Guid id){await using var db=Connection();await db.OpenAsync();await using var c=db.CreateCommand();c.CommandText="SELECT SourceBytes FROM dbo.FormDefinitions WHERE Id=@Id";P(c,"@Id",id);return await c.ExecuteScalarAsync() as byte[];}
 public async Task<List<FormEntry>> EntriesAsync(Guid id,AppUser user){await using var db=Connection();await db.OpenAsync();await using var c=db.CreateCommand();c.CommandText="SELECT TOP(500) Payload,Revision FROM dbo.FormEntries WHERE DefinitionId=@Id AND (@Admin=1 OR CreatedBy=@User OR EXISTS(SELECT 1 FROM OPENJSON(Payload,'$.Assignees') WHERE TRY_CONVERT(uniqueidentifier,value)=@User)) ORDER BY UpdatedAt DESC";P(c,"@Id",id);P(c,"@Admin",user.Role==Roles.Admin);P(c,"@User",user.Id);var result=new List<FormEntry>();await using var r=await c.ExecuteReaderAsync();while(await r.ReadAsync()){var e=JsonSerializer.Deserialize<FormEntry>(r.GetString(0))!;e.Revision=r.GetInt32(1);if(Services.FormRuntime.CanView(e,user))result.Add(e);}return result;}
 public async Task<FormEntry?> EntryAsync(Guid id){await using var db=Connection();await db.OpenAsync();await using var c=db.CreateCommand();c.CommandText="SELECT Payload,Revision FROM dbo.FormEntries WHERE Id=@Id";P(c,"@Id",id);await using var r=await c.ExecuteReaderAsync();if(!await r.ReadAsync())return null;var e=JsonSerializer.Deserialize<FormEntry>(r.GetString(0))!;e.Revision=r.GetInt32(1);return e;}
 public async Task SaveEntryAsync(FormEntry e,int expected,IReadOnlyList<ModuleBlob>? files=null){await using var db=Connection();await db.OpenAsync();await using var tx=(SqlTransaction)await db.BeginTransactionAsync();e.Revision=expected+1;e.UpdatedAt=DateTimeOffset.UtcNow;await using var c=db.CreateCommand();c.Transaction=tx;c.CommandText=expected==0?"INSERT dbo.FormEntries(Id,DefinitionId,CreatedBy,Revision,UpdatedAt,Payload) VALUES(@Id,@Def,@By,@Rev,@At,@Json)":"UPDATE dbo.FormEntries SET Revision=@Rev,UpdatedAt=@At,Payload=@Json WHERE Id=@Id AND Revision=@Expected";P(c,"@Id",e.Id);P(c,"@Def",e.DefinitionId);P(c,"@By",e.CreatedBy);P(c,"@Rev",e.Revision);P(c,"@At",e.UpdatedAt);P(c,"@Json",JsonSerializer.Serialize(e));P(c,"@Expected",expected);if(await c.ExecuteNonQueryAsync()!=1)throw new ConcurrencyConflictException();foreach(var f in files??[]){await using var upload=db.CreateCommand();upload.Transaction=tx;upload.CommandText="INSERT dbo.FormFiles(Id,EntryId,Content) VALUES(@Id,@Entry,@Bytes)";P(upload,"@Id",f.Id);P(upload,"@Entry",e.Id);upload.Parameters.Add("@Bytes",SqlDbType.VarBinary,-1).Value=f.Bytes;await upload.ExecuteNonQueryAsync();}await SqlNotificationStore.InsertAsync(db,tx,Services.NotificationRouting.Form(e));await tx.CommitAsync();}
 public async Task<List<FormEntry>> TasksAsync(AppUser user){await using var db=Connection();await db.OpenAsync();await using var c=db.CreateCommand();c.CommandText="SELECT TOP(500) Payload,Revision FROM dbo.FormEntries WHERE JSON_VALUE(Payload,'$.State')<>'Completed' AND ((JSON_VALUE(Payload,'$.Step')='0' AND CreatedBy=@User) OR EXISTS(SELECT 1 FROM OPENJSON(Payload,'$.Assignees') a WHERE a.[key]=JSON_VALUE(Payload,'$.Step') AND TRY_CONVERT(uniqueidentifier,a.value)=@User)) ORDER BY UpdatedAt DESC";P(c,"@User",user.Id);var result=new List<FormEntry>();try{await using var r=await c.ExecuteReaderAsync();while(await r.ReadAsync()){var e=JsonSerializer.Deserialize<FormEntry>(r.GetString(0))!;e.Revision=r.GetInt32(1);if(Services.FormRuntime.CanAct(e,user))result.Add(e);}}catch(SqlException ex)when(ex.Number==208){return [];}return result;}
 public async Task<byte[]?> FileAsync(Guid id){await using var db=Connection();await db.OpenAsync();await using var c=db.CreateCommand();c.CommandText="SELECT Content FROM dbo.FormFiles WHERE Id=@Id";P(c,"@Id",id);return await c.ExecuteScalarAsync() as byte[];}
}
